from author import C,S,R,P,T
c=C('函数与极限')
S(c,'课程路线与最少符号',[R('极限与连续',r"\lim_{x\to a}f(x),\quad f(a)"),R('求导与积分',r"f'(x),\quad \int f(x)\,dx"),T('做题顺序','认题型 → 查条件 → 写步骤')],[P('欢迎来到一小时学完高等数学上。这节课面向第一次备考高数的大学生，重点是认出题型，选对公式，把常见基础题的步骤写完整。我们不展开证明。视频按极限、求导、积分和微分方程依次推进，遇到练习先暂停自己算，再看答案。及格最终还取决于本校考卷和你的实际练习。',[1,2],['先抓基础计算与固定题型','例题暂停动手，避免只看不算']),P('先认识几个会反复出现的记号。f括号x表示把x代入函数；箭头表示趋近，极限符号下面说明趋向哪里。函数右上角的一撇表示一阶导数，两撇表示二阶导数。积分号后面的dx说明对x积分，字母C通常表示任意常数。接下来每次只增加当前做题需要的规则。',[1,2,3],['每题先判题型，再查使用条件','积分变量与常数要分清'])],[],kind='overview')
S(c,'极限先代入，再看形式',[R('能直接代入时',r"\lim_{x\to 1}(x^2+2x)=3"),R('零比零需要继续处理',r"\lim_{x\to 1}\frac{x^2-1}{x-1}"),R('因式分解后约分',r"\frac{(x-1)(x+1)}{x-1}=x+1\quad(x\ne1)"),R('结果',r"\lim_{x\to1}(x+1)=2")],[P('极限题拿到手，先尝试代入趋近的数。多项式直接代入就能算，第一行得到三。若分子分母都变成零，这个零比零只是提醒你还没算完，不能写成零，也不能说分母零所以极限必不存在。先检查能否分解、约分或使用下面的等价替换。',[1,2],['零比零不是最终答案','先代入识别形式']),P('第二题把x平方减一分解成x减一乘x加一，约掉公共因子。极限是在一点附近计算，附近的x不等于一，所以这一步合法。化简后再代入，答案是二。写出这一行分解和约分，比直接猜答案更容易拿到过程分，也能让阅卷者看到你的处理方法。',[3,4],['可约掉附近非零的公共因子','化简后再代入'])],['等价无穷小替换'])
S(c,'等价无穷小：先背常用表',[R('条件',r"u\to0"),R('三角函数',r"\sin u\sim u,\quad\tan u\sim u,\quad1-\cos u\sim\frac{u^2}{2}"),R('对数与指数',r"\ln(1+u)\sim u,\quad e^u-1\sim u"),R('反三角与幂',r"\arcsin u\sim u,\quad\arctan u\sim u"),R('固定非零常数',r"(1+u)^\alpha-1\sim\alpha u\quad(\alpha\ne0)")],[P('这张表是极限计算的优先记忆项。先看前提：里面的小量u必须趋于零，三角函数按弧度计算。正弦u和正切u都可以与u等价，一减余弦u对应u平方的一半。最后这一项的平方和二分之一最容易漏，写草稿时先把它们圈出来。',[1,2],['角度按弧度；内部小量趋于零','一减余弦对应二阶小量']),P('再记三组：自然对数一加u对应u，e的u次方减一对应u，反正弦和反正切也对应u。最后是固定常数α的幂，一加u的α次方减一，对应α乘u。计算前还要保证表达式在附近有定义，比如实数对数内部要为正，不能无视定义域直接套表。',[3,4,5],['α是固定非零常数','先确认附近表达式有定义'])],['等价无穷小替换'])
S(c,'等价替换：先整理乘除结构',[R('例题',r"\lim_{x\to0}\frac{\sin3x\,\ln(1+2x)}{x^2}"),R('分别识别完整小量',r"\sin3x\sim3x,\quad\ln(1+2x)\sim2x"),R('代入并约分',r"\lim_{x\to0}\frac{3x\cdot2x}{x^2}=6"),R('保留差的整体，不能先把指数项换成一','e^x-1\\sim x')],[P('看第一道例题，分子是两个因子相乘，适合分别等价替换。正弦里面是三x，就替成三x；对数里面是一加二x，整个对数替成二x。不要看到三角函数就只写一个x，也不要把对数里面的系数二弄丢。两个内部小量都随x趋于零，条件满足。',[1,2],['把整个因子识别出来','内部系数必须保留']),P('替换后分子是六x平方，约掉分母的x平方，结果六。等价替换用于乘除关系时最稳妥；加减中有抵消风险，不能随便逐项换。比如e的x次方减一，要把这一整个差当作小量。若先把e的x次方替成一再相减，就会把决定答案的部分直接抹掉。',[3,4],['乘除因子可分别替换','出现相减时先识别整体'])],['等价无穷小替换'])
S(c,'无穷小的比较：统一做比值',[R('条件',r"\alpha(x)\to0,\quad\beta(x)\to0"),R('高阶与等价',r"\frac{\alpha}{\beta}\to0:\ \alpha=o(\beta);\qquad\frac{\alpha}{\beta}\to1:\ \alpha\sim\beta"),T('同阶与低阶','比值趋于有限非零常数：同阶；比值绝对值趋于无穷：前者低阶'),R('例子',r"\frac{x^2}{x}\to0,\quad\frac{2x}{x}\to2,\quad\frac{\sin x}{x}\to1")],[P('比较两种无穷小，不要只凭名字或指数猜，最稳的统一办法是做前者除以后者的极限。比值为零，前者是后者的高阶无穷小，也就是更快靠近零；比值为一才叫等价。这里高阶不是数值更大，恰好是趋近零时相对更小，这个方向要记牢。',[1,2],['先确认两者都趋于零','比较顺序决定高阶或低阶']),P('比值趋于有限非零常数叫同阶，常数不一定是一；比值绝对值趋于无穷，前者是低阶。例子中x平方除以x趋于零，所以x平方高阶；二x与x同阶但不等价；正弦x与x等价。如果比值振荡没有极限，不能硬塞进这些需要比值极限的分类。',[3,4],['同阶不一定等价','等价对应比值恰好趋于一'])],['无穷小的比较'])
S(c,'左右极限：分段题分别代入',[R('分段表达式',r"f(x)=x+1\ (x<0),\quad f(x)=2x+c\ (x>0)"),R('左边与右边',r"\lim_{x\to0^-}f(x)=1,\quad\lim_{x\to0^+}f(x)=c"),R('两侧一致才有双侧极限','1=c\\quad\\Longleftrightarrow\\quad c=1'),R('点值可以不等于极限','f(0)=9,\\quad\\lim_{x\\to0}f(x)=1')],[P('分段函数在分界点求极限，先判断从哪一边靠近。x从零左边来，用x加一，得到一；从右边来，用二x加c，得到c。不要因为题目在等号处规定了某个函数值，就把那个值同时拿来充当左右极限，附近表达式和点值是两件要分别检查的事。',[1,2],['左极限用左侧表达式','右极限用右侧表达式']),P('双侧极限存在，要求左右极限都存在并且相等，所以这里c必须为一。即使把零处的函数值另设成九，只要左右表达式不变，极限仍然可以是一。下一章判断连续时，才要求这个极限再等于实际点值。分段题先写左右两行，通常就能清楚拿到参数条件。',[3,4],['先比左右极限，再看点值','左右不同则双侧极限不存在'])],['左右极限'])
S(c,'第二类重要极限：算指数乘小量',[R('通用模板',r"u\to0,\quad uv\to L,\quad1+u>0"),R('结论',r"(1+u)^v\to e^L"),R('例题',r"\lim_{x\to0}(1+2x)^{3/x}"),R('只算这个乘积',r"(2x)\frac{3}{x}=6\quad\Longrightarrow\quad e^6")],[P('第二类重要极限常出现底数趋于一、指数变得很大的形式。先把底数写成一加小量u，再算小量乘指数v的极限。如果这个乘积趋于有限数L，而且底数在附近为正，就得到e的L次方。不要只看到一的无穷次方就直接写e，指数最后还要经过这次计算。',[1,2],['底数先写成一加小量','必须确认底数在附近为正']),P('例题小量是二x，指数是三除以x，两者相乘得到六，所以结果是e的六次方。若把趋近变量换成正整数n，一减二除以n的n次方，小量乘指数就是负二，结果e的负二次方。正负号来自底数中的变化方向，不要在背模板时把减号自动丢掉。',[3,4],['保留小量前的系数和正负号','结果是e的乘积极限次方'])],['第二类重要极限'])
S(c,'极限练习',[R('计算',r"\lim_{x\to0}\frac{1-\cos2x}{x^2}")],[P('先暂停做一道极限题：一减余弦二x，除以x平方，x趋于零。请选择合适的等价式，特别留意整体平方后系数会变成多少，以及公式里原本就有的二分之一。先写出分子的等价小量，再约分，不要凭印象只报一个数字。',[1],['先写分子的等价式','答案在下一页'])],['等价无穷小替换'],kind='question')
S(c,'极限练习答案',[R('替换整体',r"1-\cos2x\sim\frac{(2x)^2}{2}=2x^2"),R('约分',r"\lim_{x\to0}\frac{2x^2}{x^2}=2")],[P('答案是二。这里u等于二x，所以u平方的一半，应该写成二x整体平方再除以二，也就是二x平方。把它除以分母的x平方即可。若你的答案是一或四，通常是忘了内部系数要平方，或者忘了原公式中的二分之一。把完整替换步骤写出来，就能避免这两类失分。',[1,2],['括号内的二x整体平方','本题结果二'])],['等价无穷小替换'],kind='answer')

c=C('连续与间断点')
S(c,'连续的三项检查',[R('连续要求',r"\lim_{x\to a}f(x)=f(a)"),R('先有定义，再比较左右极限与点值','\\lim_{x\\to a^-}f(x)=\\lim_{x\\to a^+}f(x)=f(a)'),R('例题',r"f(x)=\frac{\sin x}{x}\ (x\ne0),\quad f(0)=k"),R('连续补点',r"\lim_{x\to0}\frac{\sin x}{x}=1\quad\Longrightarrow\quad k=1")],[P('连续定义在考试里可以拆成三项检查：点上有函数值，附近有有限的极限，而且这个极限等于点值。分段函数仍然先算左右，再检查与点值是否一致。若只证明左右极限相等，还没有证明函数一定连续，因为题目可能把点值故意填错，或者根本没定义点值。',[1,2],['有点值、有有限极限、两者相等','分段处先分别算左右']),P('例题把非零时的函数设为正弦x除以x，零处填k。附近极限是一，所以要连续就取k等于一。这种题常叫补定义或求参数，作答直接写极限值，再令点值与它相等。闭区间端点的连续只检查从区间内部靠近的一侧，不必额外要求区间外也有表达式。',[3,4],['补点的值等于极限','区间端点检查相应单侧'])],['连续的定义'])
S(c,'间断点分类：先看两侧是否有限',[R('可去：有限极限相同，但点值不对或未定义','\\lim_{x\\to a^-}f=\\lim_{x\\to a^+}f=L\\in\\mathbb{R}'),R('跳跃间断',r"\lim_{x\to a^-}f=L_1,\quad\lim_{x\to a^+}f=L_2,\quad L_1\ne L_2"),R('第二类例子',r"\frac1x\ (x=0),\qquad\sin\frac1x\ (x=0)"),T('第一类间断点','可去间断点，或跳跃间断点')],[P('间断点分类先算左右极限。两侧都有限而且相等，只是没点值或点值不对，叫可去间断；两侧都有限但不相等，叫跳跃间断。这两种合称第一类。记忆时抓住“可去能补点、跳跃两边不同”，不要把任何没有定义的点都直接叫第二类。',[1,2],['可去：有限且左右相等','跳跃：有限但左右不同']),P('如果至少一侧不能得到有限极限，就归入第二类。比如一除以x在零附近无界，是无穷间断；正弦一除以x不断振荡，是振荡间断。遇到含绝对值、分母为零或振荡项的题，先列可疑位置，再逐个算左右。分类依据是附近极限的表现，不是函数式看起来有多复杂。',[3,4],['可去与跳跃属于第一类','无穷或振荡属于第二类'])],['间断点分类'])
S(c,'闭区间连续：三类结论',[R('有界与最值',r"f\in C[a,b]\ \Longrightarrow\ m\le f(x)\le M"),R('介值性质',r"f(a)<k<f(b)\ \Longrightarrow\ \exists\xi\in(a,b):f(\xi)=k"),R('零点条件',r"f(a)f(b)<0\ \Longrightarrow\ \exists\xi\in(a,b):f(\xi)=0"),R('例题',r"f(x)=x^3+x-1,\quad f(0)=-1,\quad f(1)=1")],[P('题目出现闭区间连续，优先想到三组工具：一定有界且能取得最大最小值，能够取得端点值之间的中间值，以及端点异号时内部至少有一个零点。最值定理要求闭区间，若换成开区间，就不能不加检查地照搬。写定理题的过程，先交代连续范围，再写端点计算。',[1,2,3],['先核对闭区间与连续','至少有一个不等于恰好一个']),P('比如x立方加x减一，在零到一连续，两个端点分别为负一和一，因此中间至少有一个零点。到这里已经完成零点存在性的标准写法，不需要解出三次方程。若还问唯一性，可再证明导数三x平方加一恒正，从而严格递增；端点异号本身并不能保证唯一。',[3,4],['存在性：连续加端点异号','唯一性需要额外理由'])],['闭区间连续函数的性质'])
S(c,'连续练习',[R('题目',r"f(x)=\frac{x^2-1}{x-1}\ (x\ne1),\quad f(1)=5"),T('需要判断','x=1：是否连续？间断类型？怎样补点？')],[P('这道题在x不等于一时取x平方减一除以x减一，却把一处的值设成五。请先约分算极限，再判断这一点是否连续；如果不连续，属于可去还是跳跃。最后想一想，把五改成哪个数，能让这一处连续。先自己写完这三项，再继续。',[1,2],['先约分求极限，再与点值比较','答案在下一页'])],['连续的定义','间断点分类'],kind='question')
S(c,'连续练习答案',[R('极限',r"\lim_{x\to1}\frac{x^2-1}{x-1}=2"),R('点值不等于极限',r"f(1)=5\ne2"),T('结论','可去间断点；把 f(1) 改为2即可连续')],[P('极限是二，而点值是五，因此不连续。左右极限都存在、有限而且相等，所以是可去间断点，不是跳跃。把函数值改成二即可补成连续。做这类选择题时，不要因为分母在一处为零就直接选无穷间断，要先检查有没有能约掉的公共因子。',[1,2,3],['本题为可去间断','补点值应为二'])],['连续的定义','间断点分类'],kind='answer')
